draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // clouds
  ctx.fillStyle = 'white';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 100 * Math.cos(t + i), H/2 + 50 * Math.sin(t + i), 20 + 10 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  // tree
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W/2 - 50, H - 100, 100, 100);
  ctx.fill();
  ctx.stroke();

  // leaves
  for (let i = 0; i < 10; i++) {
    ctx.beginPath();
    ctx.arc(W/2 - 50 + 20 * Math.cos(t + i), H - 100 + 20 * Math.sin(t + i), 10 + 5 * Math.sin(t + i), 0, 2 * Math.PI);
    ctx.fill();
    ctx.stroke();
  }

  ctx.restore();
}
